d=json.load(open('docs/api/marketing.json'))
# marketing.json structure: find set_ads_strength
def walk(o, path=''):
    if isinstance(o,dict):
        if 'name' in o and o.get('name')=='set_ads_strength':
            print(json.dumps(o, indent=1))
            return True
        for k,v in o.items():
            if walk(v, path+'/'+str(k)): return True
    elif isinstance(o,list):
        for i,x in enumerate(o):
            if walk(x, path+f'[{i}]'): return True
    return False
if not walk(d):
    # fallback: print keys
    print('keys:', list(d.keys()) if isinstance(d,dict) else type(d))
