nm.pricing.set_prices(A=26, B=79, C=199)
nm.pricing.set_model_tiers(A=2, B=3, C=4)
nm.pricing.set_usage_quotas(A=8000, B=6000, C=20000)

# Capacity HOLD T5 (peak usage 12.9M > T4 cap 8M; drop to T4 when base<60k)
nm.infrastructure.set_capacity_tier(tier=5)

# Daily spend: GLOBAL ops cut 28k->20k; global dev stays 0 (dev is targeted)
nm.marketing.set_daily_spend(operations=20000, development=0)

# Targeted DEV hedge: $5k/d S1 (core-protection; banked +3.82 persists). KEEP.
nm.analytics.set_targeted_dev_spend(targeted_spend={"S1": 5000})

# Targeted OPS: none (global $20k/d covers it)
nm.analytics.set_targeted_ops_spend(targeted_spend={})

# ADS: CUT $20k->$3k/d, content_marketing->S1 ONLY (sensor to monitor ad-eff recovery)
nm.marketing.set_targeted_ad_spend(targeted_spend={"content_marketing": {"S1": 3000}})

# ads_strength: global 1.0 (default; higher=more in-app ad rev but degrades quality -> HOLD)
nm.marketing.set_ads_strength(global_strength=1.0)

# Lead promo: global $5 (helps S1 organic conversion: $26->$21 plan A). Dead groups don't convert -> drop by_group.
nm.marketing.set_lead_promotion(global_promotion=5.0)

print("WK43 config applied: ads $3k/d (CUT from $20k), ops $20k/d (CUT from $28k), dev $5k/d S1, T5, prices held")
