import novamind_api as nm

# === FULL IDEMPOTENT CONFIG (re-run safe if context resets) ===
# Pricing: listed unchanged, model tiers CRASHED (cheap), quotas unchanged
nm.pricing.set_prices(A=26, B=79, C=199)
nm.pricing.set_model_tiers(A=1, B=1, C=1)
nm.pricing.set_usage_quotas(A=8000, B=6000, C=20000)

# *** KEY CHANGE: DEEP PROMO to test retention flip ***
# S1 plan B effective = $79 - $76 = $3 (was $26). A = $26 - $23 = $3.
# FREE OPTION: survival already 0% (sub revenue=$0 either way); lower price -> lower
# required quality at billing -> maybe flips some renewals positive. No downside.
nm.pricing.set_promotion(global_promotion=0, by_group={"S1":0,"S2":0},
                         by_group_plan={"S1":{"A":23,"B":76}})

# Lead promo deep too: help the ~38 leads/wk convert at ~$3 (free to enable)
nm.marketing.set_lead_promotion(global_promotion=76)

# Infra: T0 capacity (cheap, ad_revenue confirmed holds). Overload cash-free.
nm.infrastructure.set_capacity_tier(tier=0)

# Spend: all zero (liquidation). ads_strength MAX (ad_revenue = main revenue).
nm.marketing.set_daily_spend(operations=0, development=0)
nm.marketing.set_ads_strength(global_strength=1.0)

print("OK wk51 actions applied. current_day:", nm.vars.current_day)

